<?php
function x1_file(string $n):string{return X1_ROOT.'/data/'.$n.'.json';}function x1_defaults():array{return['settings'=>['brand'=>'X1 WAVEO Panel','language_default'=>'en','panel_api_public_url'=>'','remote_activation_mode'=>'lab','premium_mode'=>'lab','functions_region'=>'europe-west1','firebase_project_id'=>'','companion_url'=>'https://iptvcompanion.web.app/?id=','companion_apk_url'=>'https://www.waveo.tv/api/download/latest-apk?app=companion','security'=>['login_attempts'=>5,'lock_minutes'=>15]],'admins'=>[],'portals'=>[],'activation_jobs'=>[],'premium_codes'=>[],'api_log'=>[],'audit'=>[],'notifications'=>[],'premium_offers'=>[],'companion'=>[],'function_tests'=>[],'pairing_sessions'=>[],'cloud_playlists'=>[],'sync_mappings'=>[],'cloud_users'=>[],'cloud_snapshots'=>[],'sync_conflicts'=>[],'sync_events'=>[],'pairing_rate_limits'=>[],'sync_deltas'=>[],'routing_manifest'=>[],'routing_map'=>[],'m3u_links'=>[]];}function x1_read(string $n){$d=x1_defaults();$db=x1_db();if($db){$row=x1_db_one('SELECT value_json FROM kv_store WHERE name=?',[$n]);if($row){$v=json_decode((string)$row['value_json'],true);return is_array($v)?$v:($d[$n]??[]);}}$p=x1_file($n);if(!is_file($p))return $d[$n]??[];$v=json_decode((string)file_get_contents($p),true);return is_array($v)?$v:($d[$n]??[]);}function x1_write(string $n,$v):void{$db=x1_db();$json=json_encode($v,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);if($db){x1_db_exec('INSERT INTO kv_store(name,value_json,updated_at) VALUES(?,?,?) ON CONFLICT(name) DO UPDATE SET value_json=excluded.value_json,updated_at=excluded.updated_at',[$n,$json,date('c')]);return;}$p=x1_file($n);$tmp=$p.'.tmp';file_put_contents($tmp,json_encode($v,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)."\n",LOCK_EX);rename($tmp,$p);}function x1_id():string{return bin2hex(random_bytes(8));}function x1_admin_start():void{if(session_status()!==PHP_SESSION_ACTIVE){session_name('x1waveo');$secure=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off');session_set_cookie_params(['lifetime'=>0,'path'=>'/','secure'=>$secure,'httponly'=>true,'samesite'=>'Strict']);session_start();x1_security_headers();}}function x1_lang():string{x1_admin_start();if(isset($_GET['lang'])&&in_array($_GET['lang'],['en','pt'],true)){$_SESSION['lang']=$_GET['lang'];if(!headers_sent())setcookie('x1_lang',$_GET['lang'],time()+31536000,'/');}return $_SESSION['lang']??($_COOKIE['x1_lang']??x1_read('settings')['language_default']??'en');}function tr(string $en,string $pt):string{return x1_lang()==='pt'?$pt:$en;}function h($s):string{return htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');}function x1_csrf():string{x1_admin_start();if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));return $_SESSION['csrf'];}function x1_check_csrf():void{if(!hash_equals(x1_csrf(),(string)($_POST['csrf']??'')))throw new RuntimeException('Invalid CSRF token');}function x1_require_admin():void{x1_admin_start();if(empty($_SESSION['admin'])){header('Location: ../index.php');exit;}}function x1_audit(string $action,string $detail=''):void{$db=x1_db();$user=(string)($_SESSION['admin']??'system');$uid=(string)($_SESSION['user_id']??'');$ip=x1_client_ip();$at=date('c');if($db){$prev=(string)x1_db_scalar('SELECT event_hash FROM audit_events ORDER BY rowid DESC LIMIT 1',[],'');$payload=json_encode(['at'=>$at,'user'=>$user,'uid'=>$uid,'action'=>$action,'detail'=>$detail,'ip'=>$ip],JSON_UNESCAPED_SLASHES);$hash=hash('sha256',$prev.'|'.$payload);x1_db_exec('INSERT INTO audit_events(id,at,user_name,user_id,action,target,detail_json,ip,prev_hash,event_hash) VALUES(?,?,?,?,?,?,?,?,?,?)',[x1_id(),$at,$user,$uid,$action,'',json_encode(['detail'=>$detail],JSON_UNESCAPED_SLASHES),$ip,$prev,$hash]);return;}$r=x1_read('audit');$r[]=['id'=>x1_id(),'at'=>$at,'admin'=>$user,'action'=>$action,'detail'=>$detail,'ip'=>$ip];if(count($r)>2000)$r=array_slice($r,-2000);x1_write('audit',$r);}function x1_api_log(string $action,string $result='success',int $http=200,array $meta=[]):void{$db=x1_db();$at=date('c');$ip=x1_client_ip();if($db){x1_db_exec('INSERT INTO api_events(id,at,action,result,http,duration_ms,device_id,session_id,ip,meta_json) VALUES(?,?,?,?,?,?,?,?,?,?)',[x1_id(),$at,$action,$result,$http,(int)($meta['duration_ms']??0),(string)($meta['deviceId']??''),(string)($meta['sessionId']??''),$ip,json_encode($meta,JSON_UNESCAPED_SLASHES)]);return;}$r=x1_read('api_log');$r[]=['id'=>x1_id(),'at'=>$at,'action'=>$action,'result'=>$result,'http'=>$http,'ip'=>$ip,'meta'=>$meta];if(count($r)>5000)$r=array_slice($r,-5000);x1_write('api_log',$r);}function x1_json($v,int $http=200):never{http_response_code($http);header('Content-Type: application/json; charset=utf-8');echo json_encode($v,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;}function x1_portals_payload():array{$rows=array_values(array_filter(x1_read('portals'),fn($r)=>!isset($r['enabled'])||$r['enabled']));return['portals'=>array_map(fn($r)=>['name'=>(string)($r['name']??'Service'),'url'=>(string)($r['url']??'')],$rows)];}